// Schrift holen (ALLY 43): Schrift des Firmendesigns einmal vom Server aus bei Google Fonts laden und als eine CSS-Datei mit eingebetteten Schriftdateien
// (woff2, Zeichensätze latin und latin-ext, Stärken 400–800) ablegen. Der Browser lädt sie dann von Ally (/neu?datei=schrift), nie von Google.
// Gibt es die Schrift nicht oder ist Google nicht erreichbar: leere Datei mit fassung „fehler“ (Systemschrift; neuer Versuch frühestens nach einem Tag).
const s = String(($input.first().json || {}).schrift || '').trim();
const fnv = t => { let a = 2166136261, b = 5381; for (let i = 0; i < t.length; i++) { const c = t.charCodeAt(i); a ^= c; a = Math.imul(a, 16777619) >>> 0; b = (Math.imul(b, 33) + c) >>> 0; } return a.toString(16).padStart(8, '0') + b.toString(16).padStart(8, '0'); };
const ergebnis = (inhalt, fassung, hinweis) => [{ json: { inhalt, fassung: fassung || fnv(inhalt), bytes: Buffer.byteLength(inhalt, 'utf8'), quelle: s, hinweis } }];
if (!s) return ergebnis('', 'leer', 'Im Firmendesign ist keine Schrift eingetragen.');
if (!/^[A-Za-z0-9 ]{2,60}$/.test(s)) return ergebnis('', 'fehler', 'Ungültiger Schriftname.');
// Moderner Browser als Kennung, sonst liefert Google kein woff2
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36';
const holen = (url, binaer) => this.helpers.httpRequest({ method: 'GET', url, headers: { 'User-Agent': UA }, encoding: binaer ? 'arraybuffer' : 'text', timeout: 20000 });
const fam = encodeURIComponent(s).replace(/%20/g, '+');
let css = '';
try { css = String(await holen('https://fonts.googleapis.com/css2?family=' + fam + ':wght@400;500;600;700;800&display=swap')); }
catch (e) {
  // Nicht jede Schrift hat alle Stärken: dann nur die Grundstärke
  try { css = String(await holen('https://fonts.googleapis.com/css2?family=' + fam + '&display=swap')); }
  catch (e2) { return ergebnis('', 'fehler', 'Schrift bei Google Fonts nicht gefunden oder nicht erreichbar: ' + String(e2.message || e2).slice(0, 200)); }
}
const bloecke = [...css.matchAll(/\/\*\s*([a-z0-9-]+)\s*\*\/\s*(@font-face\s*\{[^}]*\})/g)].filter(m => m[1] === 'latin' || m[1] === 'latin-ext');
if (!bloecke.length) return ergebnis('', 'fehler', 'Keine passenden Schriftdateien gefunden.');
// Variable Schriften: Google nennt dieselbe Datei für jede Stärke – dann nur einmal laden, mit Stärkebereich (z. B. 400 800)
const jeDatei = new Map();
for (const m of bloecke) {
  const u = /url\((https:\/\/fonts\.gstatic\.com\/[A-Za-z0-9\/_.-]+\.woff2)\)/.exec(m[2]);
  if (!u) continue;
  const w = Number((/font-weight:\s*(\d+)/.exec(m[2]) || [])[1] || 400);
  const x = jeDatei.get(u[1]);
  if (x) x.staerken.push(w); else jeDatei.set(u[1], { teil: m[1], block: m[2], staerken: [w] });
}
const teile = []; let gesamt = 0;
for (const [url, x] of jeDatei) {
  let datei;
  try { datei = Buffer.from(await holen(url, true)); } catch (e) { return ergebnis('', 'fehler', 'Schriftdatei nicht erreichbar.'); }
  if (datei.length < 100 || datei.subarray(0, 4).toString('latin1') !== 'wOF2') return ergebnis('', 'fehler', 'Schriftdatei unplausibel.');
  gesamt += datei.length;
  if (gesamt > 1500000) return ergebnis('', 'fehler', 'Schrift zu groß (über 1,5 MB).');
  const von = Math.min(...x.staerken), bis = Math.max(...x.staerken);
  const block = x.block.replace(/font-weight:\s*\d+;/, 'font-weight: ' + (von === bis ? von : von + ' ' + bis) + ';')
    .replace(/src:\s*url\([^)]*\)\s*format\(['"]woff2['"]\)/, "src: url(data:font/woff2;base64," + datei.toString('base64') + ") format('woff2')");
  if (/https?:/i.test(block)) return ergebnis('', 'fehler', 'Unerwartete Adresse in der Schrift.');
  teile.push('/* ' + x.teil + ' */\n' + block);
}
if (!teile.length) return ergebnis('', 'fehler', 'Keine Schriftdateien geladen.');
const inhalt = '/* ' + s + ' – von Ally ausgeliefert (Google Fonts, Lizenz OFL/Apache), Stand ' + new Date().toISOString().slice(0, 10) + ' */\n' + teile.join('\n');
return ergebnis(inhalt, '', teile.length + ' Schriftdateien, ' + gesamt + ' Bytes');
